import{_ as o,o as a,c as i,a0 as l}from"./chunks/framework.Bud-GSzw.js";const g=JSON.parse('{"title":"更新履歴","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),d={name:"changelog.md"};function t(c,e,r,n,h,s){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="更新履歴" tabindex="-1">更新履歴 <a class="header-anchor" href="#更新履歴" aria-label="Permalink to &quot;更新履歴&quot;">​</a></h1><h2 id="_1-1-5-2026-09-26" tabindex="-1">[1.1.5] - 2026-09-26 <a class="header-anchor" href="#_1-1-5-2026-09-26" aria-label="Permalink to &quot;[1.1.5] - 2026-09-26&quot;">​</a></h2><h3 id="🚀-高速化" tabindex="-1">🚀 高速化 <a class="header-anchor" href="#🚀-高速化" aria-label="Permalink to &quot;🚀 高速化&quot;">​</a></h3><ul><li>モデル登録時にフィールド別の値変換器と更新の検証経路を準備します。2万行の変換を比較したローカル測定中央値は0.194秒から0.166秒になりました（基本型・日時・リストを含むモデル）。</li><li>型情報の解析を繰り返さないようにし、1万行取得のローカル測定中央値が同期版で0.098秒から0.068秒、非同期版で0.108秒から0.074秒になりました。</li><li><code>LIMIT</code> と <code>OFFSET</code> をSQLパラメータに変更しました。1,000回のページング検索のローカル測定中央値は0.0341秒から0.0315秒になりました。</li><li><code>__in</code> の使われないJSON変換を削除しました。整数1,000件の条件を500回生成するローカル測定では0.138秒から0.091秒になりました。</li></ul><h3 id="🐞-修正" tabindex="-1">🐞 修正 <a class="header-anchor" href="#🐞-修正" aria-label="Permalink to &quot;🐞 修正&quot;">​</a></h3><ul><li>ドキュメント用依存関係の既知脆弱性を解消し、任意依存の <code>cryptography</code> をPython 3.10以上の修正版に限定しました。</li><li>非同期キャンセル後も実行中のSQLite呼び出しを保護し、開いたトランザクションをロールバックするようにしました。同期版でも割り込み時にロールバックします。</li><li><code>update()</code> が更新値を検証し、独自バリデータやモデル設定がある場合は対象行をトランザクション内で検証するようにしました。</li><li>既存テーブルとモデルの列、型、主キー、NULL制約、全文検索対象列が異なる場合、<code>register()</code> で <code>SchemaMismatchError</code> を送出するようにしました。</li><li>既存テーブルへ全文検索を追加した場合、登録済みの行も検索できるようにしました。</li></ul><h3 id="📚-ドキュメント" tabindex="-1">📚 ドキュメント <a class="header-anchor" href="#📚-ドキュメント" aria-label="Permalink to &quot;📚 ドキュメント&quot;">​</a></h3><ul><li>エラー／例外ガイド、バックアップ例、必要列だけの取得、非同期の一括取得、続き位置ページングの説明を更新しました。</li></ul><h3 id="⚠️-互換性" tabindex="-1">⚠️ 互換性 <a class="header-anchor" href="#⚠️-互換性" aria-label="Permalink to &quot;⚠️ 互換性&quot;">​</a></h3><ul><li>Python 3.9では <code>encryption</code>・<code>all</code>・<code>dev</code> extrasから <code>cryptography</code> をインストールしません。コアのPython 3.9対応は継続します。</li><li>無効な部分更新はPydanticの <code>ValidationError</code>、互換性のないテーブルの登録は <code>SchemaMismatchError</code> を送出します。モデル変更時はテーブルを明示的に移行してください。</li></ul><hr><h2 id="_1-1-4-2026-06-22" tabindex="-1">[1.1.4] - 2026-06-22 <a class="header-anchor" href="#_1-1-4-2026-06-22" aria-label="Permalink to &quot;[1.1.4] - 2026-06-22&quot;">​</a></h2><h3 id="🐞-修正-1" tabindex="-1">🐞 修正 <a class="header-anchor" href="#🐞-修正-1" aria-label="Permalink to &quot;🐞 修正&quot;">​</a></h3><ul><li>SQLite識別子をSQL生成前に検証し、複合インデックスに未知のフィールドが含まれる場合は拒否するようにしました。</li><li>未対応の生SQL断片を文字列フィルタとして渡した場合、SQLへ素通しせず <code>QueryValidationError</code> を送出するようにしました。</li><li>非同期版のクエリ検証を同期版と揃え、未知フィールド検証とモデル定義に基づくフィルタ値シリアライズを追加しました。</li><li>非同期版で <code>date</code> / <code>datetime</code> / <code>list</code> / <code>dict</code> のフィルタが正しく動くようにしました。</li><li><code>__in</code> の通常ケースを修正し、空コレクションは0件一致として扱うようにしました。</li><li><code>offset</code> のみを指定した場合もSQLiteで有効な無制限 <code>LIMIT</code> 句を生成するようにしました。</li><li><code>limit</code> / <code>offset</code> で負数、小数、真偽値、文字列を拒否するよう検証を厳格化しました。</li><li><code>insert_many()</code> に異なるモデル型が混在した場合、明確に <code>TypeError</code> を送出するようにしました。</li><li>読み取り処理と接続終了を既存ロックで直列化し、実行中のクエリと <code>close()</code> が競合しないようにしました。</li><li><code>vacuum()</code> と非同期版の <code>execute_raw()</code> を既存ロックで保護しました。</li></ul><h3 id="🧪-テスト" tabindex="-1">🧪 テスト <a class="header-anchor" href="#🧪-テスト" aria-label="Permalink to &quot;🧪 テスト&quot;">​</a></h3><ul><li>危険な文字列フィルタ、非同期版のフィールド検証、シリアライズ対象フィルタ値、<code>__in</code>、offset単独指定、ページネーション型検証、混在モデル一括挿入の回帰テストを追加しました。</li></ul><h3 id="📚-ドキュメント-1" tabindex="-1">📚 ドキュメント <a class="header-anchor" href="#📚-ドキュメント-1" aria-label="Permalink to &quot;📚 ドキュメント&quot;">​</a></h3><ul><li>APSW 全機能アクセスに向けた段階的な実装計画を追加しました。</li></ul><h3 id="⚠️-互換性-1" tabindex="-1">⚠️ 互換性 <a class="header-anchor" href="#⚠️-互換性-1" aria-label="Permalink to &quot;⚠️ 互換性&quot;">​</a></h3><ul><li>文字列フィルタは <code>&quot;age &gt; 10&quot;</code> や <code>&quot;name = &#39;Alice&#39;&quot;</code> のような単純比較のみサポートします。複雑な条件は <code>age__gte=10</code> のようなキーワードフィルタ、または明示的な raw SQL を使ってください。</li><li>コアパッケージのPython 3.9対応は維持します。ただし、一部の開発・オプション依存関係はPython 3.9向けに最新のセキュリティ修正版ホイールを提供していません。信頼できない入力を扱う場合、<code>speed</code>・<code>encryption</code>・<code>dev</code> extrasはPython 3.10以上で利用してください。</li></ul><hr><h2 id="_1-1-1-2026-05-16" tabindex="-1">[1.1.1] - 2026-05-16 <a class="header-anchor" href="#_1-1-1-2026-05-16" aria-label="Permalink to &quot;[1.1.1] - 2026-05-16&quot;">​</a></h2><h3 id="🚀-追加" tabindex="-1">🚀 追加 <a class="header-anchor" href="#🚀-追加" aria-label="Permalink to &quot;🚀 追加&quot;">​</a></h3><ul><li><strong>明示的トランザクション</strong>: 手動でトランザクションを制御するための <code>atomic()</code> コンテキストマネージャを <code>NyanSQLite</code> に、<code>async with atomic()</code> を <code>NyanSQLiteAIO</code> に追加しました。</li><li><strong>入れ子構造のトランザクション</strong>: ネスト（入れ子）された <code>atomic()</code> ブロックのサポートを追加しました。</li></ul><h3 id="🔄-変更" tabindex="-1">🔄 変更 <a class="header-anchor" href="#🔄-変更" aria-label="Permalink to &quot;🔄 変更&quot;">​</a></h3><ul><li><strong>スレッドセーフ</strong>: <code>NyanSQLite</code> で <code>threading.RLock</code> を使用するように変更し、スレッド安全性を向上させました。</li><li><strong>非同期安全性</strong>: <code>NyanSQLiteAIO</code> において、<code>atomic()</code> 使用時のデッドロックを防ぐためにリエントラントな非同期ロックを実装しました。</li></ul><hr><h2 id="_1-1-0-2026-05-16" tabindex="-1">[1.1.0] - 2026-05-16 <a class="header-anchor" href="#_1-1-0-2026-05-16" aria-label="Permalink to &quot;[1.1.0] - 2026-05-16&quot;">​</a></h2><h3 id="🚀-追加-1" tabindex="-1">🚀 追加 <a class="header-anchor" href="#🚀-追加-1" aria-label="Permalink to &quot;🚀 追加&quot;">​</a></h3><ul><li><strong>非同期サポート</strong>: <code>NyanSQLiteAIO</code> クラスによる <code>asyncio</code> の完全サポート。</li><li><strong>パフォーマンス向上</strong>: <code>asyncio.to_thread</code> 内での効率的な行処理により、読み取り操作を最適化。</li><li><strong>ドキュメント更新</strong>: 非同期利用に関する日英のドキュメントを追加。</li></ul><h3 id="🔄-変更-1" tabindex="-1">🔄 変更 <a class="header-anchor" href="#🔄-変更-1" aria-label="Permalink to &quot;🔄 変更&quot;">​</a></h3><ul><li><code>NyanSQLiteAIO</code> の <code>query</code>, <code>select</code>, <code>search</code> メソッドの内部最適化。</li><li>同期版 <code>NyanSQLite</code> クラスにおいて、読み取り操作のロック保持時間を最小化。</li></ul><hr><h2 id="_1-0-1-2026-05-15" tabindex="-1">[1.0.1] - 2026-05-15 <a class="header-anchor" href="#_1-0-1-2026-05-15" aria-label="Permalink to &quot;[1.0.1] - 2026-05-15&quot;">​</a></h2><h3 id="🐞-修正-2" tabindex="-1">🐞 修正 <a class="header-anchor" href="#🐞-修正-2" aria-label="Permalink to &quot;🐞 修正&quot;">​</a></h3><ul><li>軽微なバグ修正とパフォーマンスの改善。</li></ul><hr><h2 id="_1-0-0-2026-05-15" tabindex="-1">[1.0.0] - 2026-05-15 <a class="header-anchor" href="#_1-0-0-2026-05-15" aria-label="Permalink to &quot;[1.0.0] - 2026-05-15&quot;">​</a></h2><h3 id="🚀-追加-2" tabindex="-1">🚀 追加 <a class="header-anchor" href="#🚀-追加-2" aria-label="Permalink to &quot;🚀 追加&quot;">​</a></h3><ul><li><strong>Pydantic v2 対応</strong>: Pydanticモデルをそのままデータベーススキーマとして利用可能。</li><li><strong>Djangoライクなクエリ構文</strong>: <code>__gte</code>, <code>__in</code>, <code>__like</code> などの直感的なフィルタリングをサポート。</li><li><strong>FTS5 全文検索</strong>: SQLiteのFTS5拡張を利用した高速な全文検索機能。</li><li><strong>自動インデックス管理</strong>: <code>Indexed[T]</code> や <code>UniqueIndexed[T]</code> アノテーションによるB-treeインデックスの自動生成。</li><li><strong>複合インデックス</strong>: Pydanticの <code>Field</code> メタデータを介した <code>CompositeIndex</code> のサポート。</li><li><strong>透過的な型処理</strong>: <code>dict</code> や <code>list</code> などの複雑な型を自動的にJSONとしてシリアライズ/デシリアライズ。</li><li><strong>WALモードのサポート</strong>: パフォーマンスと並行性の向上のため、デフォルトでWAL（Write-Ahead Logging）モードを有効化。</li><li><strong>コンテキストマネージャ対応</strong>: <code>with</code> 構文による自動的なコネクション終了処理。</li></ul><h3 id="🔄-変更-2" tabindex="-1">🔄 変更 <a class="header-anchor" href="#🔄-変更-2" aria-label="Permalink to &quot;🔄 変更&quot;">​</a></h3><ul><li>NyanSQLite の初期公開リリース。</li></ul><hr>',43)])])}const q=o(d,[["render",t]]);export{g as __pageData,q as default};
